import React, { useState } from "react";
import PageTransition from "../components/animations/PageTransition";
import PageHeader from "../components/PageHeader";
import { Send, Bot, User } from "lucide-react";

function AIChatAssistant() {
  const [message, setMessage] = useState("");
  const [chat, setChat] = useState([
    { text: "Hello! I am your AI Legal Assistant. How can I help you with your legal issues today?", sender: "ai" }
  ]);

  const sendMessage = () => {
    if (message.trim() === "") return;

    const newChat = [...chat, { text: message, sender: "user" }];

    // Auto-reply
    setTimeout(() => {
      setChat(prev => [...prev, {
        text: "I understand your concern. Based on initial analysis, this might require a specialized lawyer. Would you like me to find one for you?",
        sender: "ai"
      }]);
    }, 1000);

    setChat(newChat);
    setMessage("");
  };

  return (
    <PageTransition>
      <PageHeader 
        title="AI Legal Assistant" 
        subtitle="Get instant answers to your legal queries from our smart AI."
      />

      <div className="max-w-4xl mx-auto px-6 py-12">
        <div className="bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-[600px]">
          {/* Chat Messages */}
          <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50">
            {chat.map((msg, index) => (
              <div
                key={index}
                className={`flex ${msg.sender === "user" ? "justify-end" : "justify-start"}`}
              >
                <div className={`flex gap-3 max-w-[80%] ${msg.sender === "user" ? "flex-row-reverse" : ""}`}>
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center shrink-0 shadow-md ${msg.sender === "user" ? "bg-emerald-600 text-white" : "bg-white text-emerald-600 border border-emerald-100"}`}>
                    {msg.sender === "user" ? <User size={20} /> : <Bot size={20} />}
                  </div>
                  <div className={`p-4 rounded-2xl shadow-sm ${msg.sender === "user" ? "bg-emerald-600 text-white rounded-tr-none" : "bg-white text-slate-800 border border-slate-100 rounded-tl-none"}`}>
                    <p className="leading-relaxed">{msg.text}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Chat Input */}
          <div className="p-6 bg-white border-t border-slate-100">
            <div className="flex gap-2 overflow-x-auto pb-4 scrollbar-hide no-scrollbar">
               {["Draft a contract", "Divorce laws in Pakistan", "Property dispute", "Child custody"].map(q => (
                 <button 
                  key={q}
                  onClick={() => setMessage(q)}
                  className="whitespace-nowrap px-4 py-2 bg-emerald-50 text-emerald-700 rounded-full text-xs font-bold border border-emerald-100 hover:bg-emerald-600 hover:text-white transition-all shadow-sm"
                 >
                    {q}
                 </button>
               ))}
            </div>
            <div className="flex gap-4 items-center bg-slate-50 p-2 rounded-2xl border border-slate-200">
              <input
                type="text"
                placeholder="Describe your legal issue..."
                className="flex-1 bg-transparent px-4 py-2 focus:outline-none text-slate-700 font-medium"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && sendMessage()}
              />
              <button 
                onClick={sendMessage}
                className="bg-emerald-600 text-white p-3 rounded-xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-600/30 active:scale-95"
              >
                <Send size={24} />
              </button>
            </div>
            <p className="text-center text-[10px] text-slate-400 mt-4 uppercase tracking-tighter font-bold">Powered by LawBridge Smart Intelligence</p>
          </div>
        </div>
      </div>
    </PageTransition>
  );
}

export default AIChatAssistant;
